<?php
namespace App\Policies;use App\Domain\Tenancy\TenantContext;use App\Models\{StickerBatch,User};final class StickerBatchPolicy{private function allowed(User$u):bool{return$u->memberships()->where('status','ACTIVE')->whereIn('role_code',['SYSTEM_ADMIN','PLATFORM_ADMIN','STICKER_CUSTODIAN'])->exists();}public function viewAny(User$u):bool{return$this->allowed($u);}public function view(User$u,StickerBatch$m):bool{return$this->allowed($u)&&$m->stocks()->where('custodian_tenant_id',app(TenantContext::class)->id())->exists();}public function create(User$u):bool{return$this->allowed($u);}public function update(User$u,StickerBatch$m):bool{return false;}public function delete(User$u,StickerBatch$m):bool{return false;}}
